const p0 = await Promise.all(scoped.map(ticket => nl`Does ticket say or imply that the customer may cancel or move to another provider?`(ticket)));
const k0 = scoped.filter((_, j) => p0[j]);
const sorted = [...k0].sort((a, b) => Number(a.id.slice(1)) - Number(b.id.slice(1)));
const labels = await Promise.all(sorted.map(ticket => ticket_kind(ticket)));
return sorted.map((x, j) => ({ id: x.id, kind: labels[j] }));

