const ITEMS = [ { "id": "T1", "customer": "Lumen Studio", "plan": "free", "seats": 29, "opened": "2026-03-08", "text": "Since yesterday's update, the dashboard shows the wrong numbers. We are not going anywhere, we just want this fixed. Nobody on our side can work right now." }, { "id": "T2", "customer": "Harbor Media", "plan": "enterprise", "seats": 142, "opened": "2026-03-18", "text": "Our invoice lists 142 seats but we only have 141. Two of our managers already asked me to look at other tools. We can live with it for a few weeks." }, { "id": "T3", "customer": "Ivy Schools", "plan": "pro", "seats": 201, "opened": "2026-03-25", "text": "We can live with it for a few weeks. Our contract is up next month and this makes renewal hard to justify. How do I share a dashboard with a client? I could not find it in the docs." }, { "id": "T4", "customer": "Granite Legal", "plan": "free", "seats": 120, "opened": "2026-03-17", "text": "We downgraded in February but are still billed at the old rate. Our whole team is stuck until this is sorted. If this is not fixed this week we will move to another provider." }, { "id": "T5", "customer": "Cobalt Foods", "plan": "enterprise", "seats": 121, "opened": "2026-03-22", "text": "We can live with it for a few weeks. We cancelled our team meeting to look into this, so a quick reply would help. We would love an option to schedule reports weekly; today there is none." }, { "id": "T6", "customer": "Evergreen Clinic", "plan": "enterprise", "seats": 133, "opened": "2026-03-17", "text": "We were charged twice for January. No rush, whenever you get to it. We are not going anywhere, we just want this fixed." }, { "id": "T7", "customer": "Brightline", "plan": "enterprise", "seats": 95, "opened": "2026-03-03", "text": "Since yesterday's update, the calendar sync shows the wrong numbers. No rush, whenever you get to it. Thanks for the help, otherwise we are very happy with the product." }, { "id": "T8", "customer": "Delta Print", "plan": "free", "seats": 87, "opened": "2026-03-11", "text": "Nobody on our side can work right now. Since yesterday's update, the invoice view shows the wrong numbers. Our contract is up next month and this makes renewal hard to justify." }, { "id": "T9", "customer": "Arbor Labs", "plan": "pro", "seats": 80, "opened": "2026-03-06", "text": "We can live with it for a few weeks. Our invoice lists 80 seats but we only have 79. We are considering cancelling our subscription over this." }, { "id": "T10", "customer": "Nimbus Retail", "plan": "enterprise", "seats": 124, "opened": "2026-03-20", "text": "We are not going anywhere, we just want this fixed. The the export page throws an error whenever we upload a CSV. This stops our month-end close completely." } ];
/** Every ticket in the system, with its text. */
export function tickets(): Ticket[] { return ITEMS; }
/** The tickets with plan equal to value. */
export function by_plan(value: string): Ticket[] { return ITEMS.filter(x => x.plan === value); }
/** The tickets whose opened (YYYY-MM-DD) falls in [start, end]. */
export function opened_between(start: string, end: string): Ticket[] { return ITEMS.filter(x => x.opened >= start && x.opened <= end); }
